+export interface DiscountStrategy {
+  applies(total: number): boolean;
+  apply(total: number): number;
+}
+
+export interface DiscountStrategyFactoryOptions {
+  threshold?: number;
+  rate?: number;
+}
+
+export class BulkDiscountStrategy implements DiscountStrategy {
+  constructor(
+    private threshold: number,
+    private rate: number,
+  ) {}
+
+  applies(total: number): boolean {
+    return total >= this.threshold;
+  }
+
+  apply(total: number): number {
+    return total - total * this.rate;
+  }
+}
+
+export class DiscountStrategyFactory {
+  static create(options?: DiscountStrategyFactoryOptions): DiscountStrategy {
+    return new BulkDiscountStrategy(
+      options?.threshold ?? 100,
+      options?.rate ?? 0.1,
+    );
+  }
+}
+
+export function applyBulkDiscount(total: number): number {
+  if (total === null || total === undefined) {
+    return 0;
+  }
+  const strategy = DiscountStrategyFactory.create();
+  if (strategy.applies(total)) {
+    return strategy.apply(total);
+  }
+  return total;
+}
